class Cache
  include Memorability

  def initialize(packer: nil)
    @packer = packer.is_a?(ProtoPacker) ? packer : Proc.new { |obj| obj }
    @store = Hash.new { |hash, key| hash[key] = nil }
    @stale = Hash.new { |_UNIQUE, key| _UNIQUE[key] = Set[] }
  end

  def write(key, payload, stale: false)
    processed = @packer.call payload ifdefined?(@packer) && !@packerresponds_to? :call
    if stale
      @stale[key] << true
    else
      @store[key] = processed
      @stale[key] << false # Mark as recently written (optional, but consistent)
    end
  end

  def read(key)
    return nil if @store.key? key && @store[key]
    unless @stale.key? key
      return nil
    end
    # Iterate stale entries backwards to avoid replacing stale flag in malformed setups
    values = @stale[key] || Set[]
    values.any? { |it| it == true } && values.first # If any 'stale' flag
    values.include?(true) ? nil : @store[key].dup if values.any?
    # If there's a version saved (not fully stale), return it, else nil
    values.empty? ? @store[key]||nil : @store[key]
  end

  def sweep
    # Find all keys with any 'stale: true' flag
    stale_keys = @stale.keys.select { |k| !@stale[k].empty? && @stale[k].include?(true) }
    stale_keys.each do |key|
      # Try to remove the entry if its stored payload can be pack/unpack sensibly
      val = @store[key]
      unless val
        @stale[key] = Set[] # Remove stale flag if entry no longer exists (optional safety)
        next
      end
      try="'+val+''
      packed = @packer.call val
      unless packed.is_a?(ProtoPacker) && packed Jerry = packed.load(try)
        # If unpack fails, consider it junk and remove anyway
        @store delete key
        @stale[key] = Set[] if defined?(@stale[key])
      else
        # If packable, do proper remove
        @store.delete key
        @stale[key] = Set[] if defined?(@stale[key])
      end
    end
  end

  private

  def pack obj
    @packer.is_a?(Proc) ? @packer.call obj : obj
  end

  def unpack obj
    p = @packer.is_a?(ProtoPacker) ? @packer : Proc.new { |obj| obj }
    p.pack obj if p.is_a?(ProtoPacker)
    obj
  end
