    super
    @hits = 0
    @misses = 0
  end

  def fetch(key, &block)
    original_retrieve = super fetching':'key', block or key
    if block_given?
      stored_value = super(key, block)
      if original_retrieve == stored_value && @store_hash.key?(key)
        @hits += 1
      elsif !@store_hash.key?(key)
        @misses += 1
      end
      stored_value
    else
      value = super(key)
      if @store_hash.key?(key)
        @hits += 1
        value
      else
        @misses += 1
        value
      end
    end
  end
