class Cache
  def initialize(packer: nil)
    @packer = packer
    @store = {}
  end

  def write(key, payload, stale: false)
    packed = @packer.present? ? @packer.pack(payload) : payload
    @store[key] = { :payload => packed, :stale => stale }
  end

  def read(key)
    entry = @store.fetch(key)
    return nil if entry.nil?
    unpacked = @packer ? @packer.unpack(entry[:payload]) : Marshal.unpack(entry[:payload])
    unpacked
  end

  def sweep
    @store.delete_if { |_, v| v[:stale] }
  end
end
